const ElephantPieces = forwardRef(function ElephantPieces({className, pieceClassName}, ref) {
    return (
        <svg
            ref={ref}
            className={className}
            viewBox="0 0 1006 596"
            fill="#DEDEDE"
            xmlns="http://www.w3.org/2000/svg"
            style={{overflow: "visible"}}
        >
            {PIECES.map((p, i) => (
                <path
                    key={i}
                    className={pieceClassName}
                    data-x={p.x}
                    data-y={p.y}
                    data-r={p.r}
                    d={p.d}
                />
            ))}
        </svg>
    );
});

export default ElephantPieces;
